from abc import ABC, abstractmethod

# Dependency Inversion Principle (DIP)
class NotificationService(ABC):
    @abstractmethod
    def send(self, msg):
        pass

class EmailService(NotificationService):
    def send(self, msg):
        print(f"Emailing: {msg}")

